export const ksCommands=["Berlutut di hadapanku dan cium punggung tanganku.","Peluk aku dari belakang dan bisikkan bahwa aku berharga bagimu.","Sentuh wajahku perlahan, seakan kau baru pertama kali melihatku.","Genggam kedua tanganku, tatap mataku, dan tahan diam selama 20 detik.","Cium keningku, lalu bisikkan satu alasan kenapa kau memilihku.","Duduk di dekat kakiku dan sandarkan kepalamu di pahaku selama satu lagu penuh.","Belai rambutku perlahan tanpa berhenti selama satu menit penuh.","Cium telapak tanganku, satu per satu jarinya.","Peluk aku erat dan jangan lepaskan sampai aku memberi izin.","Bisikkan di telingaku satu hal yang membuatmu tertarik padaku malam ini.","Duduk di pangkuanku dan lingkarkan tanganmu di leherku.","Rangkul pinggangku dan bawa aku berdansa pelan tanpa musik.","Ambilkan aku minuman, serahkan dengan kedua tangan sambil menunduk hormat.","Pijat pundakku selama 3 menit tanpa bicara satu kata pun.","Lepaskan sepatu/kaus kakiku dan pijat kakiku selama 2 menit.","Nyalakan lilin dan redupkan lampu ruangan atas perintahku.","Siapkan camilan favoritku dan suapi aku satu per satu.","Kipasi aku perlahan selama satu lagu berlangsung.","Rapikan rambut dan pakaianku dengan lembut, seolah mempersiapkanku untuk sebuah acara penting.","Bacakan satu pesan cinta yang kau tulis dadakan untukku, sekarang juga.","Buatkan aku secangkir minuman hangat sebagai persembahan malam ini.","Kipas anginmu sendiri, lalu berikan udara sejuk itu untukku dengan tanganmu.","Bawakan bantal dan selimut, buat aku senyaman mungkin di singgasana ini.","Tuliskan tiga alasan kenapa aku pantas kau layani malam ini, bacakan keras-keras.","Panggil aku dengan sebutan \"Yang Mulia\" untuk lima menit ke depan.","Ucapkan \"aku milikmu malam ini\" dengan nada yang kau maksudkan sungguh-sungguh.","Minta izin dariku sebelum menyentuhku, untuk tiga sentuhan berikutnya.","Puji satu bagian tubuhku yang paling kau sukai, dengan kalimat lengkap dan tulus.","Ceritakan satu fantasi romantis sederhana yang ingin kau wujudkan bersamaku.","Ucapkan terima kasih atas satu hal spesifik yang kulakukan untukmu minggu ini.","Jawab \"siap, Yang Mulia\" untuk setiap perintah berikutnya sampai ronde ini berakhir.","Bisikkan satu rahasia kecil yang belum pernah kau ceritakan padaku.","Minta maaf secara jujur untuk satu hal kecil yang mengganjal di hatimu, lalu peluk aku.","Ucapkan satu janji yang ingin kau tepati untuk hubungan kita bulan ini.","Tahan tatapan mataku selama satu menit penuh tanpa tertawa atau memalingkan wajah.","Ikuti tiga gerakan tubuh yang kuperagakan, tirukan persis seperti yang kulakukan.","Jadi \"patung\" selama aku menghitung sampai 30 â€” tidak boleh bergerak sedikit pun.","Ambil satu barang yang kutunjuk dan berikan padaku sambil membungkuk hormat.","Berbisik-bisiklah seolah aku adalah rahasia terbesarmu selama satu menit.","Berjalanlah mengelilingi ruangan sekali sambil menjagaku tetap jadi pusat perhatianmu.","Buat aku tertawa dalam waktu 30 detik, dengan cara apa pun selain menggelitik.","Duduk diam di sisiku dan biarkan aku mengatur posisi dudukmu sesuka hatiku.","Berikan aku pijatan tangan sambil menjawab pertanyaan \"apa yang kau syukuri dariku hari ini?\"","Nyanyikan satu baris lagu favoritku, khusus untukku, dengan penuh perasaan.","Matikan seluruh lampu kecuali satu titik cahaya, dan bawa aku ke sana.","Putar satu lagu yang menurutmu paling menggambarkan perasaanmu padaku sekarang.","Buatkan satu \"hadiah dadakan\" dari benda apa pun yang ada di sekitarmu, berikan padaku.","Rapikan tempat duduk/tempat tidur kita berdua, siapkan untuk sisa malam ini.","Ambil selimut, ajak aku duduk berdekatan, dan peluk aku sampai ronde berikutnya dimulai.","Tuliskan satu kalimat di telapak tanganku dengan jarimu, biarkan aku menebak apa yang kau tulis.","Tanyakan kabar pasangan dengan sungguh-sungguh, lalu dengarkan tanpa memotong.","Pilih satu kenangan favorit kalian dan ceritakan mengapa itu berarti.","Buatkan pasangan minuman atau camilan sederhana.","Ucapkan satu apresiasi spesifik tentang usaha pasangan minggu ini.","Buat rencana kecil untuk quality time kalian berikutnya.","Bacakan satu kalimat penyemangat untuk pasangan dengan penuh perhatian.","Tanyakan satu hal yang bisa kamu bantu dari pasangan hari ini.","Pilih aktivitas santai untuk dilakukan bersama selama 15 menit.","Berikan pasangan kesempatan memilih lagu berikutnya.","Ceritakan satu alasan mengapa kamu menikmati waktu berdua dengannya.","Rapikan satu area kecil yang biasa kalian gunakan bersama.","Ajak pasangan membuat foto kenangan sederhana tanpa perlu dipublikasikan.","Sampaikan satu harapan baik untuk pasangan minggu ini.","Buat kesepakatan kecil agar waktu berkualitas kalian lebih teratur.","Tawarkan pelukan atau ruang pribadi, sesuai yang sedang dibutuhkan pasangan.","Pilih satu aktivitas lama yang ingin kalian hidupkan kembali.","Ucapkan satu kalimat yang membuat pasangan merasa dihargai.","Minta pasangan memilih satu kenangan untuk diceritakan kembali.","Susun jadwal singkat untuk satu kegiatan santai bersama minggu ini.","Tawarkan untuk mengerjakan satu tugas rumah yang biasanya dilakukan pasangan.","Beri pasangan satu menit untuk berbicara, lalu rangkum apa yang kamu dengar.","Pilih satu foto lama dan ceritakan perubahan yang kalian rasakan sejak saat itu.","Buat daftar tiga hal yang ingin kalian syukuri malam ini.","Siapkan tempat duduk yang nyaman untuk pasangan sebelum ronde berakhir.","Tanyakan satu pertanyaan yang belum pernah kamu tanyakan sebelumnya.","Buat rencana kejutan sederhana yang tidak membutuhkan biaya.","Ucapkan satu kalimat dukungan untuk rencana pasangan.","Tentukan satu hari tanpa ponsel selama 15 menit untuk quality time."];
export const ksCommandsExplicit=["\"Aku akan melepaskan pakaianmu dalam gerakan yang sangat lambat, jadi tahan dirimu dan jangan berani mempercepat prosesnya\"","\"Aku akan membelai area paha dalammu selama tiga menit penuh tanpa menyentuh intinya; jika kamu bergerak memohon lebih, waktunya akan kutambah\".","\"Aku hanya akan memberikan godaan di bagian luar areamu menggunakan ujung jari, rasakan ketegangan ini karena kamu belum kuizinkan menerima lebih\".","\"Aku meletakkan sesuatu yang manis di tubuhmu; diamlah dan nikmati sensasinya saat aku menjilatnya perlahan hingga bersih\".","\"Ambil ponsel ini dan rekam dirimu sendiri secara close-up saat memanaskan area sensitifmu, biarkan aku menilai secara visual dari jarak dekat\".","\"Berbaringlah dan gunakan tanganmu sendiri untuk memanaskan dirimu; tugasmu hanya memuaskan pandanganku tanpa diizinkan mempercepat tempo sedikit pun\".","\"Berbaringlah di ujung ranjang dengan kakimu menggantung ke bawah lantai; aku ingin akses visual dan sudut penuh untuk menguasaimu\".","\"Berbaringlah tengkurap dengan bantal tebal mengganjal perutmu; pasrahkan dirimu seratus persen saat aku mengambil alih kendali dari atas\".","\"Beri tahu aku sekarang, apakah meteran gairahmu sudah masuk di Zona Kuning? Jika ya, kita berhenti total di sini selama tiga puluh detik\".","\"Berjalanlah merangkak perlahan ke arahku, berhenti tepat di ujung kakiku, dan diam di sana tanpa mengangkat wajahmu\".","\"Berlututlah di depanku, tatap mataku, dan beri tahu aku secara rinci bagian tubuh mana dariku yang paling ingin kamu sentuh malam ini\".","\"Bermainlah dalam cahaya remang ini; tugasmu adalah menjaga siluet tubuhmu tetap melengkung sempurna di depan lensa tanpa memotong fokusku\".","\"Bernapaslah seirama denganku; jika napasmu memburu dan mendahului napasku, aku akan melepaskan sentuhanku dan membiarkanmu menggantung\".","\"Cium setiap ujung jariku satu per satu; tunjukkan lewat tatapanmu betapa kamu memohon tangan ini untuk segera menyentuhmu\".","\"Dengarkan suaraku baik-baik saat aku membisikkan fantasi nakal ini di telingamu, dan tugasmu hanya merespons dengan desahan\".","\"Duduklah di lantai; aku akan berada di belakangmu, dan kamu harus diam mematung saat tanganku mulai menjelajahi area depanmu\".","\"Fokus pada sentuhan benda lembut yang menyusuri paha dalammu ini, nikmati setiap gesekannya tanpa boleh memohon lebih\".","\"Gigit kain ini kuat-kuat agar suaramu tertahan; aku akan menguji batas kesabaranmu dengan sentuhan intens yang sangat lambat di paha dalammu\".","\"Gunakan hanya bibir dan lidahmu untuk mengeksplorasi area dadaku; lakukan dengan sangat lambat dan penuh penghormatan\".","\"Gunakan tanganmu sendiri untuk memanaskan dirimu, tapi berhenti total di batas Zona Kuning; tunjukkan wajah frustrasimu padaku\".","\"Hitung mundur dari dua puluh dengan suara berbisik lambat; setiap kali kamu mendesah atau suaramu bergetar, kamu harus mengulang dari awal\".","\"Jelaskan kepadaku dengan nada suara paling memohon, mengapa kamu merasa pantas mendapatkan klimaks malam ini; yakinkan aku\".","\"Kenakan kembali pakaian dalammu; sekarang kamu harus memohon dan merayuku secara lisan agar aku sudi melepaskannya lagi\".","\"Lepaskan semua suaramu dan mengeranglah lebih keras untukku, tapi ingat, kamu tidak akan mencapai klimaks sebelum aku yang memerintahkan\".","\"Letakkan kedua tanganmu di belakang punggung; kamu dilarang keras menyentuhku atau dirimu sendiri sampai aku memberikan izin\".","\"Menghadaplah ke cermin besar itu; aku ingin kamu menatap lurus pantulan dirimu sendiri saat pasrah menerima setiap sentuhanku dari belakang\".","\"Mulai sekarang, kamu hanya boleh menjawab pertanyaanku dengan anggukan atau gelengan sampai aku secara eksplisit mengizinkanmu berbicara\".","\"Pegang tanganku dan arahkan perlahan ke titik yang paling kamu inginkan, tapi ingat, aku yang memegang kendali penuh kapan tekanan ini akan dihentikan\".","\"Posisikan dirimu telentang dengan tangan terentang lebar; tugasmu malam ini hanyalah menjadi kanvas dan menerima apa pun yang ingin aku berikan\".","\"Posisikan tubuhmu tepat di depan kamera yang menyala ini; kamu hanya boleh bergerak mengikuti arahanku tanpa menutupi wajahmu sama sekali\".","\"Rasakan sensasi dingin dari es batu ini di lehermu, dan jangan bergerak sedikit pun saat lidahku menyusuri jejak airnya ke perutmu\".","\"Rasakan ujung es batu ini menyusuri tulang punggungmu; diamlah dan tahan desahanmu sampai esnya mencair sepenuhnya di atas kulitmu\".","\"Sekarang aku sudah menemukan ritme dan tekanan yang paling membuatmu nikmat, aku akan menguncinya dan kamu hanya perlu pasrah menerimanya\".","\"Tunjukkan padaku bagaimana kamu menyelesaikan dirimu sendiri; gunakan sisa tenagamu untuk mencapai klimaks tanpa berani memejamkan mata sekalipun\".","\"Turun dari kasur sekarang; bersandarlah di dinding dingin itu dengan kedua tangan di belakang punggung dan tunggu arahanku\".","\"Tutup matamu sekarang menggunakan kain ini, mulai detik ini kamu hanya bisa merasakan sentuhanku tanpa tahu dari mana datangnya\"."];
export const roleplayBuiltInRoles=[{"id":"bos-sekretaris","emoji":"💼","name":"Bos & Sekretaris","desc":"Kantor sudah sepi, tinggal kalian berdua dan setumpuk \"pekerjaan\".","items":[{"context":"Kalian berdua lembur berdua di kantor yang sudah sepi. Lampu ruangan lain sudah mati satu per satu.","challenge":"Sang bos memanggil sekretarisnya masuk ke ruangan untuk \"membahas laporan\" — mulai percakapan dengan nada serius yang perlahan berubah jadi menggoda."},{"context":"Sekretaris mengetuk pintu ruangan bos membawa dokumen yang \"mendesak\" untuk ditandatangani.","challenge":"Sekretaris harus membujuk bos untuk berhenti bekerja sejenak, dengan cara sekreatif mungkin, tanpa menyebut kata \"istirahat\"."},{"context":"Rapat evaluasi kinerja dadakan, hanya kalian berdua di meja rapat panjang itu.","challenge":"Bos memberi \"penilaian kinerja\" ke sekretarisnya — satu pujian tulus, satu candaan genit, dan satu perintah kecil untuk dijalankan sekarang juga."},{"context":"Hujan deras di luar, tidak ada ojek atau taksi, dan kalian berdua terjebak di kantor.","challenge":"Ciptakan alasan konyol kenapa kalian harus \"menunggu bareng\" sambil duduk berdekatan, lalu lanjutkan obrolan itu sampai terasa personal."},{"context":"Sekretaris baru saja menyelesaikan tugas besar dan bos ingin memberi apresiasi khusus.","challenge":"Bos memberi \"bonus\" berupa pujian panjang lebar plus satu pelukan hangat sebagai penutup adegan."}]},{"id":"orang-asing-bar","emoji":"🍷","name":"Orang Asing di Bar","desc":"Dua orang yang baru saja \"bertemu\" malam ini, belum saling kenal.","items":[{"context":"Kalian duduk berdampingan di sebuah bar temaram, sama-sama datang sendirian malam ini.","challenge":"Perkenalkan diri dengan nama dan profesi palsu yang lucu, lalu coba tebak mana yang bohong dari cerita pasanganmu."},{"context":"Salah satu dari kalian baru saja putus cinta dan curhat ke \"orang asing\" di sebelahnya.","challenge":"Dengarkan curhatannya sambil berperan sebagai pendengar yang penuh perhatian, lalu tawarkan untuk menemaninya minum satu gelas lagi."},{"context":"Musik live sedang dimainkan, suasana bar mulai ramai dan hangat.","challenge":"Ajak \"orang asing\" itu berdansa pelan di tempat, meski hanya berdiri berdua sambil bergoyang santai."},{"context":"Bartender salah memberi minuman dan kalian berdua kebagian gelas yang sama.","challenge":"Berpura-puralah berebut satu gelas itu sampai akhirnya sepakat untuk \"berbagi\", lengkap dengan alasan menggoda kenapa harus berbagi."},{"context":"Malam sudah larut, bar akan segera tutup dan kalian belum ingin berpisah.","challenge":"Salah satu harus mengajak yang lain melanjutkan malam ini — dengan gombalan paling berani yang bisa dipikirkan secara spontan."}]},{"id":"guru-les-privat","emoji":"📚","name":"Guru & Murid Les Privat","desc":"Sesi belajar tambahan yang perlahan lupa soal pelajaran.","items":[{"context":"Sesi les privat malam ini, buku terbuka di meja tapi konsentrasi murid mulai buyar.","challenge":"Sang guru menegur muridnya karena melamun, lalu menawarkan \"hadiah\" kecil kalau bisa fokus lima menit lagi."},{"context":"Murid kesulitan mengerjakan satu soal dan minta didekati untuk dijelaskan langsung.","challenge":"Guru duduk lebih dekat untuk membimbing, sambil sesekali menggoda muridnya karena terlalu gugup untuk fokus."},{"context":"Waktu les hampir habis tapi murid pura-pura belum paham supaya sesi diperpanjang.","challenge":"Murid harus mengarang alasan paling kreatif kenapa dia \"masih butuh bimbingan ekstra\" malam ini."},{"context":"Guru memberi ujian dadakan untuk menguji seberapa jauh muridnya sudah belajar.","challenge":"Buat tiga pertanyaan konyol bertema hubungan kalian berdua, dan yang jawabannya paling romantis dapat \"nilai sempurna\"."},{"context":"Sesi belajar selesai, guru memberi catatan penutup untuk muridnya.","challenge":"Guru menulis \"pesan rahasia\" pendek di secarik kertas dan menyerahkannya sambil tersenyum jahil."}]},{"id":"tetangga-apartemen","emoji":"🏠","name":"Tetangga Apartemen","desc":"Baru pindah ke unit sebelah, dan ternyata dinding kamar cukup tipis.","items":[{"context":"Salah satu baru pindah ke unit sebelah dan mengetuk pintu untuk berkenalan sambil membawa \"oleh-oleh\".","challenge":"Perkenalkan diri sebagai tetangga baru dan cari alasan untuk diajak masuk sebentar."},{"context":"Listrik di seluruh lantai apartemen mendadak padam malam ini.","challenge":"Salah satu mengetuk pintu tetangga minta pinjam senter atau lilin — lalu memilih untuk menunggu listrik nyala bersama-sama."},{"context":"Suara musik dari salah satu unit terlalu keras, tetangga sebelah datang untuk \"komplain\".","challenge":"Yang komplain harus berubah pikiran di tengah jalan dan malah ikut menikmati musiknya bersama pemilik unit."},{"context":"Kalian berpapasan di lorong sambil sama-sama membawa sampah ke tempat pembuangan.","challenge":"Ciptakan obrolan basa-basi paling receh yang bisa dibuat, sampai salah satu berani mengajak \"ngopi kapan-kapan\"."},{"context":"Salah satu lupa membawa kunci apartemen dan terjebak di luar unitnya sendiri.","challenge":"Tetangga menawarkan tempatnya untuk menunggu sampai tukang kunci datang — sambil diam-diam senang punya alasan untuk mengobrol lebih lama."}]},{"id":"selebriti-fan","emoji":"🌟","name":"Selebriti & Fan","desc":"Meet & greet setelah acara, dan fan-nya berani sekali malam ini.","items":[{"context":"Sesi meet & greet setelah konser, sang fan akhirnya berdiri di depan idolanya.","challenge":"Fan harus mengungkapkan kekagumannya dengan cara paling berlebihan tapi tulus, sementara sang selebriti meladeni dengan gaya percaya diri."},{"context":"Sang selebriti diam-diam terkesan dengan satu fan yang beda dari yang lain.","challenge":"Selebriti menawarkan foto berdua dengan syarat: fan itu harus berani menggandeng tangannya untuk pose itu."},{"context":"Backstage sudah sepi, tapi sang fan berhasil menyelinap untuk satu obrolan singkat.","challenge":"Ciptakan alasan kreatif kenapa fan itu \"harus\" ada di sana, lalu minta satu kenang-kenangan pribadi dari sang selebriti."},{"context":"Sang selebriti memberi kesempatan pada satu fan untuk bertanya apa saja, tanpa batasan.","challenge":"Fan bertanya satu hal yang cukup personal, dan selebriti wajib menjawabnya dengan jujur sambil menggoda balik."},{"context":"Acara sudah selesai, sang selebriti menawarkan tumpangan pulang untuk fan favoritnya.","challenge":"Selebriti mengajak fan itu naik ke mobilnya sambil melempar satu pujian yang bikin fan-nya salah tingkah."}]},{"id":"reuni-mantan","emoji":"💌","name":"Reuni \"Mantan\"","desc":"Bertemu lagi setelah lama tak bertemu — apakah rasa itu masih ada?","items":[{"context":"Kalian berpapasan tanpa sengaja di sebuah acara reuni, setelah sekian lama tidak bertemu.","challenge":"Buka percakapan dengan basa-basi canggung khas \"mantan yang ketemu lagi\", lalu perlahan cerita apa yang berubah dari kalian berdua."},{"context":"Salah satu memberanikan diri mengajak yang lain untuk mengobrol berdua, menjauh dari keramaian.","challenge":"Tanyakan satu hal yang selama ini ingin ditanyakan tapi tidak pernah sempat, lalu dengarkan jawabannya dengan serius."},{"context":"Lagu yang dulu sering diputar berdua tiba-tiba diputar di acara itu.","challenge":"Ajak \"mantan\" itu berdansa sebentar mengenang masa lalu, sambil bercerita kenangan favorit tentang lagu itu."},{"context":"Salah satu mengaku masih menyimpan satu barang kecil dari hubungan dulu.","challenge":"Ceritakan barang apa itu dan kenapa masih disimpan, dengan nada jujur dan sedikit menggoda."},{"context":"Malam semakin larut dan acara reuni akan segera berakhir.","challenge":"Putuskan bersama: mengucap selamat tinggal untuk terakhir kalinya, atau berani bilang \"aku belum siap untuk berpisah lagi\" — lalu peluk erat sebagai penutup."}]},{"id":"normal-roleplay-weekend-planner","emoji":"🗓️","name":"Perencana Akhir Pekan","desc":"Kalian menyusun akhir pekan yang menyenangkan bersama.","items":[{"context":"Kalian duduk bersama dengan kalender dan beberapa pilihan aktivitas.","challenge":"Bergantian mengusulkan satu aktivitas, lalu sepakati rencana yang membuat kalian berdua antusias."},{"context":"Hujan turun dan rencana awal kalian harus diubah.","challenge":"Buat rencana pengganti yang nyaman dilakukan di rumah dan bagi tugasnya secara adil."},{"context":"Kalian ingin mencoba sesuatu yang belum pernah dilakukan bersama.","challenge":"Pilih satu hal sederhana untuk dicoba minggu ini dan jelaskan alasan pilihanmu."},{"context":"Kalian menemukan beberapa resep sederhana yang belum pernah dicoba.","challenge":"Pilih satu resep, bagi tugasnya, dan buat jadwal untuk memasaknya bersama."},{"context":"Kalian memiliki satu sore kosong tanpa rencana.","challenge":"Bergantian mengusulkan aktivitas selama 15 menit hingga menemukan kegiatan yang disukai bersama."},{"context":"Kalian ingin membuat kenangan baru tanpa mengeluarkan banyak biaya.","challenge":"Rancang kencan sederhana dengan anggaran terbatas dan presentasikan idenya secara bergantian."},{"context":"Salah satu dari kalian sedang lelah setelah menjalani hari yang panjang.","challenge":"Tanyakan kebutuhannya, lalu susun rencana malam yang nyaman untuk kalian berdua."},{"context":"Kalian melihat kalender dan menyadari jadwal bulan depan cukup padat.","challenge":"Tentukan satu waktu khusus untuk quality time dan sepakati cara menjaganya."},{"context":"Kalian menemukan album foto lama saat sedang merapikan ruangan.","challenge":"Pilih tiga foto dan ceritakan kenangan yang paling kalian sukai dari masing-masing foto."},{"context":"Kalian ingin memperbaiki suasana hati setelah hari yang melelahkan.","challenge":"Bergantian memilih satu hal kecil yang bisa membuat malam ini terasa lebih nyaman."},{"context":"Kalian sedang menunggu makanan atau minuman disiapkan.","challenge":"Buat permainan tanya jawab singkat dengan pertanyaan yang menyenangkan dan ringan."},{"context":"Kalian ingin membuat tradisi baru yang mudah dilakukan.","challenge":"Ciptakan satu tradisi mingguan, beri nama, dan tentukan kapan tradisi itu dimulai."},{"context":"Kalian mempunyai waktu luang singkat sebelum melanjutkan aktivitas.","challenge":"Gunakan waktu itu untuk saling memberi apresiasi secara bergantian tanpa mengulang alasan."}]}];
