export const explicitTopicPool=explicitPools.flatMap(category=>category.topics||[]);
export const truthPool=truthOrDarePools.find(category=>category.name==="Truth")?.topics||[];
export const darePool=truthOrDarePools.find(category=>category.name==="Dare")?.topics||[];
export function randomTopic(pool,used=new Set()){const available=pool.filter(item=>!used.has(item));const source=available.length?available:pool;if(!source.length)return "";const value=source[Math.floor(Math.random()*source.length)];used.add(value);return value;}

