const normalizeTopicKey=value=>String(value).normalize("NFKC").trim().replace(/\s+/g," ").toLocaleLowerCase("id-ID");
const uniqueTopics=(items,extra=[])=>{const seen=new Set();return [...items,...extra].filter(item=>{const key=normalizeTopicKey(item);if(seen.has(key))return false;seen.add(key);return true;});};
const uniqueRoles=(items,extra=[])=>{const seen=new Set();return [...items,...extra].filter(item=>{const key=String(item.id||item.name||"").trim().toLocaleLowerCase("id-ID");if(seen.has(key))return false;seen.add(key);return true;});};
